"""Select a subset of tasks from all_tasks, keeping some % from each temp.
    Args:
        all_tasks: List of tasks like ['00001:001', ...]
        ratio: A number between 0-1, specifying how many of the tasks to keep.
    Returns:
        tasks: An updated list, with the ratio number of tasks.
    """
def get_subset_tasks(all_tasks: Any, ratio: Any) -> object {
    if (len(all_tasks) == 0) {
        return all_tasks;
    }
    assert (0.0 <= ratio <= 1.0);
    all_tasks = sorted(all_tasks);
    samples_to_keep = int((len(all_tasks) * ratio));
    return all_tasks[::(len(all_tasks) // samples_to_keep)][:samples_to_keep];
}

""" Takes in a single year's data during a single simulation and updates the balance. """
def update_balance(
    iteration_balance: Any, contribution: Any, current_year_tuple: Any
) -> object {
    STOCK_RATE = 0;
    BOND_RATE = 1;
    STOCK_PCT = 2;
    iteration_balance = iteration_balance + contribution;
    stock_balance = iteration_balance * current_year_tuple[STOCK_PCT];
    bond_balance = iteration_balance * (1 - current_year_tuple[STOCK_PCT]);
    stock_balance += stock_balance * current_year_tuple[STOCK_RATE];
    bond_balance += bond_balance * current_year_tuple[BOND_RATE];
    iteration_balance = stock_balance + bond_balance;
    return iteration_balance;
}

"""This method deduplicates data object results within a query, so that ls displays data objects
    one time, instead of once for every replica."""
def _replica_results_dedup(queries: Any) -> object {
    deduplicated_queries = [];
    for query in queries {
        new_query = query.copy();
        if ("results" in query) {
            objects_seen = {};
            dedup_results = [];
            results = query["results"];
            for result in results {
                if (result["type"] == "dataobject") {
                    full_name = result["full_name"];
                    if (full_name not in objects_seen) {
                        objects_seen[full_name] = 1;
                        dedup_results.append(result);
                    }
                } else {
                    dedup_results.append(result);
                }
            }
            new_query["results"] = dedup_results;
        }
        deduplicated_queries.append(new_query);
    }
    return deduplicated_queries;
}

